// Written inefficiently
function search(items) {
  let results = [];
  for (let item of items) {
    for (let i = 0; i < items.length; i++) {
      if (items[i].id === item.id) {
        results.push(item);
      }
    }
  }
  return results;
}

// Developer: "This language is slow!"

good_example.code:
// Developer: "I wrote inefficient code. Here's the fix."
function search(items) {
  const itemMap = new Map(items.map(i => [i.id, i]));
  return items.filter(item => itemMap.has(item.id));
}

// Problem solved. Owns the mistake.

